"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["42205"],{23130(e,n,t){t.r(n),t.d(n,{metadata:()=>a,default:()=>c,frontMatter:()=>r,contentTitle:()=>s,toc:()=>h,assets:()=>l});var a=JSON.parse('{"id":"qiangguo/erikson","title":"","description":"Last night, England\'s final comeback against Argentina may seem coincidental, but it contains deeper significance. The bold move of putting on three strikers and converting Gerrard to right-back shows Eriksson\'s hot-blooded side at last, and he has finally found England\'s strongest formation","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/qiangguo/erikson.md","sourceDirName":"qiangguo","slug":"/qiangguo/erikson","permalink":"/en/qiangguo/erikson","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"erikson","title":"","hide_table_of_contents":true,"sidebar_label":"The passionate Eriksson has finally found England\'s strongest championship lineup!"},"sidebar":"qiangguoSidebar","previous":{"title":"To the netizen \\"Math\\" who thinks Peking University is superior to Tsinghua \u2014 if you have any academic spirit, stand up and admit your mistakes!","permalink":"/en/qiangguo/admitmistake"},"next":{"title":"Analyzing forum membership composition from Qiangguo Forum\'s deep-water traffic, with corresponding suggestions","permalink":"/en/qiangguo/forumprofolio"}}'),i=t(74848),o=t(28453);let r={id:"erikson",title:"",hide_table_of_contents:!0,sidebar_label:"The passionate Eriksson has finally found England's strongest championship lineup!"},s="Hot-Blooded Eriksson Has Finally Found England's Strongest Lineup for Winning the Championship!",l={},h=[];function d(e){let n={h1:"h1",header:"header",p:"p",...(0,o.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(n.header,{children:(0,i.jsx)(n.h1,{id:"hot-blooded-eriksson-has-finally-found-englands-strongest-lineup-for-winning-the-championship",children:"Hot-Blooded Eriksson Has Finally Found England's Strongest Lineup for Winning the Championship!"})}),"\n",(0,i.jsxs)(n.p,{children:["Last night, England's final comeback against Argentina may seem coincidental, but it contains deeper significance. The bold move of putting on three strikers and converting Gerrard to right-back shows Eriksson's hot-blooded side at last, and he has finally found England's strongest formation: the Christmas Tree. Simply replace the left-back from last night's final on-pitch personnel with Ashley Cole, and England's strongest lineup is born, as follows:",(0,i.jsx)("br",{}),"\nGoalkeeper: Robinson ",(0,i.jsx)("br",{}),"\nBack four (left to right): Ashley Cole / Terry / Ferdinand / Gerrard ",(0,i.jsx)("br",{}),"\nMidfield (left to right): Joe Cole, Lampard, Beckham ",(0,i.jsx)("br",{}),"\nForwards (left to right): Rooney, Crouch, Owen"]}),"\n",(0,i.jsx)(n.p,{children:"Last night Owen's two goals were assisted by Gerrard and Joe Cole respectively, perfectly demonstrating the characteristics and power of this formation. England's current greatest advantages are: the long passing of Beckham and Gerrard; the dribbling breakthroughs of Joe Cole, Rooney, and Ashley Cole; the superb long-range shooting ability of Lampard, Gerrard, Beckham, and Rooney; plus Crouch's height and Owen's speed. This formation maximizes England's attacking advantages. On the left, Joe Cole, Rooney, and Ashley Cole -- three players with exceptional breakthrough ability -- form an attacking unit focused on penetration; on the right, the long passes of Beckham and Gerrard provide tremendous firepower; through the center, the powerful long-range attacks of Lampard plus Gerrard and Beckham switching positions -- these three weapons are unrivaled in the world. The key is managing the interchange between left, center, and right attacking modes according to the situation on the pitch."}),"\n",(0,i.jsx)(n.p,{children:"Defensively, Rooney's tackling ability is superb, and Crouch can assist in forming the first layer of interception; Lampard, Beckham, and Gerrard can quickly transform into three defensive midfielders forming the second layer of interception; Ashley Cole / Terry / Ferdinand / Gerrard form the third barrier; and finally there is the increasingly miraculous Robinson. On defense, Gerrard faces the most pressure, as he must participate in the second and third defensive layers, but his ability is beyond question."}),"\n",(0,i.jsx)(n.p,{children:"Once this formation is drilled to maturity, it will be the most balanced in attack and defense in the world today, with attacking firepower not one bit weaker than Brazil's. Including Brazil, no other country can possibly have such perfect personnel configuration. Think about it -- besides England, where in the world is there a team that simultaneously possesses \"the long passing of Beckham and Gerrard, the breakthrough ability of Joe Cole, Rooney, and Ashley Cole, the superb long-range shooting of Lampard, Gerrard, Beckham, and Rooney, plus the height of Crouch and the speed of Owen\"? Facing such formidable attacking power and a more-than-respectable defense, who can escape unscathed? 2006 will be England's year!"})]})}function c(e={}){let{wrapper:n}={...(0,o.R)(),...e.components};return n?(0,i.jsx)(n,{...e,children:(0,i.jsx)(d,{...e})}):d(e)}},28453(e,n,t){t.d(n,{R:()=>r,x:()=>s});var a=t(96540);let i={},o=a.createContext(i);function r(e){let n=a.useContext(o);return a.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function s(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:r(e.components),a.createElement(o.Provider,{value:n},e.children)}}}]);